# -*- coding: utf-8 -*-
# Genere components/asteria/content_i18n.cpp : table FR -> EN,ES,DE,IT.
import re, sys

# Dictionnaire : FR EXACT (copie des sources) -> (EN, ES, DE, IT)
T = {}
def add(fr, en, es, de, it): T[fr]=(en,es,de,it)

# ---------- Dialogues ----------
add("Ainsi, c'est toi la voyageuse. Bienvenue a Valbois.","So you are the traveler. Welcome to Valbois.","Asi que tu eres la viajera. Bienvenida a Valbois.","Du bist also die Reisende. Willkommen in Valbois.","Allora sei tu la viaggiatrice. Benvenuta a Valbois.")
add("Prends cette carte : les chemins ne sont plus surs.","Take this map: the roads are no longer safe.","Toma este mapa: los caminos ya no son seguros.","Nimm diese Karte: die Wege sind nicht mehr sicher.","Prendi questa mappa: le strade non sono piu sicure.")
add("Nos gens disparaissent. Une ombre monte... Reviens me voir.","Our people vanish. A shadow is rising... Come back to me.","Nuestra gente desaparece. Una sombra crece... Vuelve a verme.","Unsere Leute verschwinden. Ein Schatten steigt auf... Komm wieder.","La nostra gente sparisce. Un'ombra cresce... Torna da me.")
add("Les Tenebres rodent jusqu'aux portes de Valbois.","The Darkness prowls to the gates of Valbois.","Las Tinieblas merodean hasta las puertas de Valbois.","Die Finsternis schleicht bis an Valbois' Tore.","Le Tenebre si aggirano fino alle porte di Valbois.")
add("Decouvre ce qui enleve les notres. Je t'en conjure.","Find out what is taking our own. I beg you.","Descubre que se lleva a los nuestros. Te lo suplico.","Finde heraus, was die Unsrigen raubt. Ich flehe dich an.","Scopri cosa rapisce i nostri. Te ne prego.")
add("Mes outils ont disparu.","My tools have gone missing.","Mis herramientas han desaparecido.","Mein Werkzeug ist verschwunden.","I miei attrezzi sono spariti.")
add("Si vous les trouvez pres de la foret, ramenez-les-moi.","If you find them near the forest, bring them back.","Si los encuentras cerca del bosque, traemelos.","Findest du sie am Wald, bring sie mir zuruck.","Se li trovi vicino al bosco, riportameli.")
add("Je vous paierai honnetement.","I will pay you fairly.","Te pagare con justicia.","Ich zahle dir ehrlich.","Ti paghero onestamente.")
add("Besoin de quelque chose ?","Need something?","Necesitas algo?","Brauchst du etwas?","Ti serve qualcosa?")
add("J'achete aussi ce que vous trouvez.","I also buy what you find.","Tambien compro lo que encuentres.","Ich kaufe auch, was du findest.","Compro anche cio che trovi.")
add("Les temps sont durs, mais on s'entraide.","Times are hard, but we help each other.","Los tiempos son duros, pero nos ayudamos.","Die Zeiten sind hart, doch wir helfen einander.","I tempi sono duri, ma ci aiutiamo.")
add("Belle journee, n'est-ce pas ?","Fine day, isn't it?","Buen dia, verdad?","Schoner Tag, nicht wahr?","Bella giornata, vero?")
add("Le maire t'a remis la carte ? Parfait.","The mayor gave you the map? Perfect.","El alcalde te dio el mapa? Perfecto.","Hat dir der Burgermeister die Karte gegeben? Perfekt.","Il sindaco ti ha dato la mappa? Perfetto.")
add("Repose-toi ici quand tu veux.","Rest here whenever you like.","Descansa aqui cuando quieras.","Ruh dich hier aus, wann du willst.","Riposati qui quando vuoi.")
add("Un voyageur ? Va donc voir le maire.","A traveler? Go see the mayor.","Un viajero? Ve a ver al alcalde.","Ein Reisender? Geh zum Burgermeister.","Un viaggiatore? Va' dal sindaco.")
add("Il t'attend, je crois.","He is expecting you, I think.","Te espera, creo.","Er erwartet dich, glaube ich.","Ti aspetta, credo.")
add("Ces empreintes ne sont d'aucune bete connue.","These tracks belong to no known beast.","Estas huellas no son de ninguna bestia conocida.","Diese Spuren stammen von keinem bekannten Tier.","Queste impronte non sono di alcuna bestia nota.")
add("Les Tenebres gagnent la foret et enlevent nos gens.","The Darkness takes the forest and our people.","Las Tinieblas ganan el bosque y se llevan a los nuestros.","Die Finsternis ergreift den Wald und raubt unsere Leute.","Le Tenebre invadono il bosco e rapiscono la nostra gente.")
add("Suivez leur piste, mais prenez garde a votre ame.","Follow their trail, but guard your soul.","Sigue su rastro, pero cuida tu alma.","Folge ihrer Spur, doch hute deine Seele.","Segui le loro tracce, ma guarda la tua anima.")
add("Je ne suis qu'un simple villageois.","I am but a simple villager.","No soy mas que un simple aldeano.","Ich bin nur ein einfacher Dorfbewohner.","Sono solo un semplice paesano.")
add("On raconte des choses etranges ces temps-ci...","Strange things are told these days...","Se cuentan cosas extranas estos dias...","Man erzahlt sich seltsame Dinge dieser Tage...","Si raccontano cose strane di questi tempi...")
add("Les herbes medicinales manquent.","Medicinal herbs are scarce.","Faltan hierbas medicinales.","Heilkrauter sind knapp.","Mancano le erbe medicinali.")
add("Pouvez-vous m'en rapporter ?","Could you bring me some?","Puedes traerme algunas?","Kannst du mir welche bringen?","Me ne porti un po'?")
add("Je vous en serai reconnaissante.","I would be grateful.","Te lo agradeceria.","Ich ware dir dankbar.","Te ne saro grata.")
add("La foret, je la connais depuis toujours.","I have always known the forest.","Conozco el bosque desde siempre.","Den Wald kenne ich seit jeher.","Conosco il bosco da sempre.")
add("Ces derniers temps, elle murmure.","Lately, it whispers.","Ultimamente, susurra.","In letzter Zeit flustert er.","Ultimamente sussurra.")
add("Ces traces... trop grandes pour un loup. Sois prudent.","These tracks... too big for a wolf. Be careful.","Estas huellas... demasiado grandes para un lobo. Ten cuidado.","Diese Spuren... zu gross fur einen Wolf. Sei vorsichtig.","Queste tracce... troppo grandi per un lupo. Fa' attenzione.")
add("Une caravane a disparu.","A caravan has vanished.","Una caravana ha desaparecido.","Eine Karawane ist verschwunden.","Una carovana e sparita.")
add("Nous devons comprendre ce qu'il s'est passe.","We must understand what happened.","Debemos entender lo que paso.","Wir mussen verstehen, was geschah.","Dobbiamo capire cosa e successo.")
add("Aidez-nous a enqueter.","Help us investigate.","Ayudanos a investigar.","Hilf uns bei der Ermittlung.","Aiutaci a indagare.")
add("Cette pierre noire gravee... un froid me saisit.","This carved black stone... a chill grips me.","Esta piedra negra grabada... un frio me invade.","Dieser gravierte schwarze Stein... mich packt die Kalte.","Questa pietra nera incisa... un freddo mi assale.")
add("C'est une relique des Tenebres, scellee jadis.","It is a relic of the Darkness, sealed long ago.","Es una reliquia de las Tinieblas, sellada antano.","Es ist ein Relikt der Finsternis, einst versiegelt.","E una reliquia delle Tenebre, sigillata un tempo.")
add("Elle porte le sceau du Coeur de Haine. Lisez les vieux traites.","It bears the seal of the Heart of Hate. Read the old treatises.","Lleva el sello del Corazon de Odio. Lee los viejos tratados.","Es tragt das Siegel des Hassherzens. Lies die alten Schriften.","Porta il sigillo del Cuore d'Odio. Leggi i vecchi trattati.")
add("Les trois contrats sont honores. La Guilde te reconnait des siens.","All three contracts are honored. The Guild claims you as its own.","Los tres contratos cumplidos. El Gremio te reconoce como suya.","Alle drei Auftrage erfullt. Die Gilde nimmt dich als die Ihre an.","I tre contratti sono onorati. La Gilda ti riconosce dei suoi.")
add("Repose-toi : d'autres missions viendront.","Rest: more missions will come.","Descansa: vendran mas misiones.","Ruh dich aus: weitere Auftrage kommen.","Riposa: verranno altre missioni.")
add("Bienvenue a la Guilde de Grand-Castel. Voici tes contrats :","Welcome to the Grand-Castel Guild. Here are your contracts:","Bienvenida al Gremio de Grand-Castel. Estos son tus contratos:","Willkommen in der Gilde von Grand-Castel. Hier deine Auftrage:","Benvenuta alla Gilda di Grand-Castel. Ecco i tuoi contratti:")
add("- Remettre le pli scelle a Tomas Venn.","- Deliver the sealed letter to Tomas Venn.","- Entregar el pliego sellado a Tomas Venn.","- Den versiegelten Brief an Tomas Venn uberbringen.","- Consegnare il plico sigillato a Tomas Venn.")
add("- Fournir 3 herbes medicinales a Iris.","- Supply 3 medicinal herbs to Iris.","- Dar 3 hierbas medicinales a Iris.","- Iris 3 Heilkrauter liefern.","- Fornire 3 erbe medicinali a Iris.")
add("- Porter une potion a Sœur Helena.","- Bring a potion to Sister Helena.","- Llevar una pocion a la Hermana Helena.","- Schwester Helena einen Trank bringen.","- Portare una pozione a Suor Helena.")
add("Le pli est deja dans ta besace. Reviens quand tout sera regle.","The letter is already in your pack. Return when all is done.","El pliego ya esta en tu morral. Vuelve cuando todo este hecho.","Der Brief ist schon in deinem Beutel. Kehr zuruck, wenn alles erledigt ist.","Il plico e gia nella tua bisaccia. Torna quando tutto sara fatto.")
add("La Guilde des Aventuriers siege a Grand-Castel.","The Adventurers' Guild sits in Grand-Castel.","El Gremio de Aventureros reside en Grand-Castel.","Die Abenteurergilde sitzt in Grand-Castel.","La Gilda degli Avventurieri ha sede a Grand-Castel.")
add("Viens m'y trouver si tu cherches des contrats.","Come find me there if you seek contracts.","Ven a buscarme alli si buscas contratos.","Komm mich dort suchen, wenn du Auftrage willst.","Vieni a cercarmi li se cerchi contratti.")
add("Le pli de la Guilde est bien arrive. Merci a toi.","The Guild's letter has arrived. Thank you.","El pliego del Gremio ha llegado. Gracias.","Der Brief der Gilde ist angekommen. Danke dir.","Il plico della Gilda e arrivato. Grazie a te.")
add("Ma roue est reparee et la route est sure. Je repars le coeur leger !","My wheel is fixed and the road is safe. I leave with a light heart!","Mi rueda esta arreglada y el camino seguro. Parto aliviado!","Mein Rad ist heil und die Strasse sicher. Ich ziehe leichten Herzens!","La mia ruota e aggiustata e la strada e sicura. Riparto sereno!")
add("Tiens, pour ta peine. La Guilde avait raison sur toi.","Here, for your trouble. The Guild was right about you.","Toma, por tu esfuerzo. El Gremio tenia razon sobre ti.","Hier, fur deine Muhe. Die Gilde hatte recht mit dir.","Tieni, per il disturbo. La Gilda aveva ragione su di te.")
add("Ma roue est brisee et Corbeau Noir rode sur la Route Royale.","My wheel is broken and Black Crow prowls the Royal Road.","Mi rueda esta rota y Cuervo Negro merodea la Ruta Real.","Mein Rad ist kaputt und Schwarzkrahe lauert auf der Konigsstrasse.","La mia ruota e rotta e Corvo Nero si aggira sulla Via Regia.")
add("Je n'ose pas repartir seule. Ecarte ce brigand, je t'en prie.","I dare not set off alone. Drive off that brigand, please.","No me atrevo a partir sola. Aparta a ese bandido, por favor.","Ich wage nicht allein zu ziehen. Vertreib den Rauber, bitte.","Non oso ripartire sola. Scaccia quel brigante, ti prego.")
add("Je saurai te recompenser.","I will reward you.","Sabre recompensarte.","Ich werde dich belohnen.","Sapro ricompensarti.")
add("Je ne reste jamais longtemps.","I never stay long.","Nunca me quedo mucho.","Ich bleibe nie lange.","Non resto mai a lungo.")
add("Les routes sont pleines de surprises.","The roads are full of surprises.","Los caminos estan llenos de sorpresas.","Die Strassen sind voller Uberraschungen.","Le strade sono piene di sorprese.")
add("Regardez mes marchandises avant que je reparte.","Look at my wares before I leave.","Mira mi mercancia antes de que me vaya.","Sieh dir meine Waren an, bevor ich gehe.","Guarda la mia merce prima che riparta.")
add("Ces herbes sauveront des vies. La Guilde en sera informee.","These herbs will save lives. The Guild will be told.","Estas hierbas salvaran vidas. El Gremio lo sabra.","Diese Krauter retten Leben. Die Gilde wird es erfahren.","Queste erbe salveranno vite. La Gilda ne sara informata.")
add("Que les tiens soient benis, voyageuse.","Blessed be your kin, traveler.","Benditos sean los tuyos, viajera.","Gesegnet seien die Deinen, Reisende.","Siano benedetti i tuoi, viaggiatrice.")
add("Des remedes ? Des baumes ?","Remedies? Balms?","Remedios? Balsamos?","Heilmittel? Salben?","Rimedi? Balsami?")
add("J'ai ce qu'il vous faut.","I have what you need.","Tengo lo que necesitas.","Ich habe, was du brauchst.","Ho cio che ti serve.")
add("Si la Guilde m'envoyait des simples, j'en manquerais moins...","If the Guild sent me herbs, I'd run short less often...","Si el Gremio me enviara hierbas, me faltarian menos...","Schickte mir die Gilde Krauter, fehlten sie seltener...","Se la Gilda mi mandasse erbe, ne mancherei meno...")
add("Que la lumiere te garde. Nos malades sont soulages.","May the light keep you. Our sick are relieved.","Que la luz te guarde. Nuestros enfermos estan aliviados.","Das Licht behute dich. Unsere Kranken sind gelindert.","Che la luce ti protegga. I nostri malati sono sollevati.")
add("Tant de miseres echouent a la Cour des Miracles...","So much misery washes up at the Court of Miracles...","Tanta miseria acaba en la Corte de los Milagros...","So viel Elend strandet am Hof der Wunder...","Tanta miseria approda alla Corte dei Miracoli...")
add("Une simple potion soulagerait nos plus faibles.","A simple potion would relieve our weakest.","Una simple pocion aliviaria a los mas debiles.","Ein einfacher Trank linderte unsere Schwachsten.","Una semplice pozione solleverebbe i piu deboli.")
add("La Guilde a promis son aide. L'apporteras-tu ?","The Guild promised its help. Will you bring it?","El Gremio prometio su ayuda. La traeras?","Die Gilde versprach Hilfe. Bringst du sie?","La Gilda ha promesso aiuto. Lo porterai?")
add("L'hermine est repartie chez sa belle. Affaire classee.","The ermine is back with its lady. Case closed.","El armino volvio con su dama. Caso cerrado.","Der Hermelin ist zuruck bei seiner Dame. Fall erledigt.","L'ermellino e tornato dalla sua bella. Caso chiuso.")
add("Reviens si tu veux vendre, pas mendier.","Come back to sell, not to beg.","Vuelve para vender, no para mendigar.","Komm zum Verkaufen wieder, nicht zum Betteln.","Torna per vendere, non per mendicare.")
add("Tu l'as deja, le bijou. File le rendre avant que je change d'avis.","You already have the jewel. Go return it before I change my mind.","Ya tienes la joya. Ve a devolverla antes de que cambie de idea.","Du hast das Schmuckstuck schon. Gib es zuruck, eh ich's mir anders uberlege.","Hai gia il gioiello. Va' a renderlo prima che cambi idea.")
add("Un collier d'hermine ? Joli, mais sans valeur pour moi.","An ermine necklace? Pretty, but worthless to me.","Un collar de armino? Bonito, pero sin valor para mi.","Eine Hermelinkette? Hubsch, doch mir wertlos.","Una collana d'ermellino? Carina, ma per me senza valore.")
add("La fille t'envoie ? Bah... il porte le deuil, pas le profit.","The girl sent you? Bah... it carries grief, not profit.","Te manda la chica? Bah... lleva duelo, no provecho.","Schickt dich das Madchen? Bah... es tragt Trauer, keinen Gewinn.","Ti manda la ragazza? Bah... porta lutto, non profitto.")
add("Tiens. Et qu'on ne dise pas que Racha n'a pas de coeur.","Here. Let none say Racha has no heart.","Toma. Que nadie diga que Racha no tiene corazon.","Hier. Keiner sage, Racha habe kein Herz.","Tieni. E non si dica che Racha non ha cuore.")
add("Je ne traite qu'avec les gens que je connais.","I only deal with people I know.","Solo trato con gente que conozco.","Ich handle nur mit Leuten, die ich kenne.","Tratto solo con gente che conosco.")
add("Reviens quand tu sauras ce que tu cherches.","Come back when you know what you seek.","Vuelve cuando sepas lo que buscas.","Komm wieder, wenn du weisst, was du suchst.","Torna quando saprai cosa cerchi.")
add("Tu l'as rendu a sa vraie place. Merci, voyageuse.","You returned it where it belongs. Thank you, traveler.","Lo devolviste a su lugar. Gracias, viajera.","Du hast es dorthin gebracht, wo es hingehort. Danke, Reisende.","L'hai reso al suo posto. Grazie, viaggiatrice.")
add("Ce blason d'hermine etait a ma mere, et avant elle, aux tiens.","This ermine crest was my mother's, and before her, your kin's.","Este blason de armino fue de mi madre, y antes, de los tuyos.","Dieses Hermelinwappen war meiner Mutter, und davor den Deinen.","Questo stemma d'ermellino era di mia madre, e prima dei tuoi.")
add("Un jour tu sauras ce que cela signifie vraiment.","One day you will know what it truly means.","Un dia sabras lo que de verdad significa.","Eines Tages wirst du wissen, was es wirklich bedeutet.","Un giorno saprai cosa significa davvero.")
add("Ce collier ! C'est bien celui de ma famille.","This necklace! It is truly my family's.","Este collar! Es el de mi familia.","Diese Kette! Sie ist wahrlich die meiner Familie.","Questa collana! E proprio quella della mia famiglia.")
add("Tu l'as repris a Racha ? Les mots me manquent.","You took it back from Racha? Words fail me.","Se lo quitaste a Racha? Me faltan las palabras.","Du hast es Racha abgenommen? Mir fehlen die Worte.","L'hai ripreso a Racha? Mi mancano le parole.")
add("Il est a toi autant qu'a moi, desormais. Garde-le.","It is as much yours as mine now. Keep it.","Ahora es tan tuyo como mio. Guardalo.","Es gehort nun dir so sehr wie mir. Behalt es.","Ora e tuo quanto mio. Tienilo.")
add("Approche, on appelle cet endroit la Cour des Miracles.","Come closer; they call this the Court of Miracles.","Acercate, llaman a esto la Corte de los Milagros.","Komm naher; man nennt dies den Hof der Wunder.","Avvicinati, chiamano questo posto la Corte dei Miracoli.")
add("On m'a pris le seul bien qui me restait : un collier d'hermine.","They took my only possession: an ermine necklace.","Me quitaron mi unico bien: un collar de armino.","Man nahm mir mein einziges Gut: eine Hermelinkette.","Mi hanno preso l'unico bene: una collana d'ermellino.")
add("Racha le brocanteur l'a monnaye. Retrouve-le, je t'en prie.","Racha the fence sold it off. Find it, I beg you.","Racha el perista lo vendio. Encuentralo, te lo ruego.","Racha der Hehler hat sie verschachert. Find sie, ich bitte dich.","Racha il ricettatore l'ha venduta. Ritrovala, ti prego.")
add("Racha traine toujours dans son coin, la-haut.","Racha still lurks in his corner, up there.","Racha sigue en su rincon, alla arriba.","Racha lungert noch in seiner Ecke, da oben.","Racha bazzica ancora nel suo angolo, lassu.")
add("Sans mon collier, je n'ai plus rien des miens.","Without my necklace, I have nothing of my kin left.","Sin mi collar, no me queda nada de los mios.","Ohne meine Kette bleibt mir nichts von den Meinen.","Senza la mia collana, non ho piu nulla dei miei.")
add("Prends l'Anneau de l'Aube, enfant des fees : il etait aux tiens.","Take the Ring of Dawn, child of the fae: it was your kin's.","Toma el Anillo del Alba, hija de las hadas: fue de los tuyos.","Nimm den Ring der Morgenrote, Feenkind: er war der Deinen.","Prendi l'Anello dell'Alba, figlia delle fate: era dei tuoi.")
add("Il affermira ta main dans tes premiers combats.","It will steady your hand in your first battles.","Afirmara tu mano en tus primeros combates.","Es festigt deine Hand in deinen ersten Kampfen.","Rinsaldera la tua mano nei primi scontri.")
add("Que l'Aube veille sur toi.","May the Dawn watch over you.","Que el Alba vele por ti.","Moge die Morgenrote uber dich wachen.","Che l'Alba vegli su di te.")
add("Approche, enfant. Je reconnais en toi le sang des fees.","Come, child. I know the fae blood in you.","Acercate, nina. Reconozco en ti la sangre de las hadas.","Komm, Kind. Ich erkenne in dir das Feenblut.","Avvicinati, bimba. Riconosco in te il sangue delle fate.")
add("J'ai quelque chose qui t'appartient de droit.","I have something that is yours by right.","Tengo algo que te pertenece por derecho.","Ich habe etwas, das dir von Rechts wegen gehort.","Ho qualcosa che ti spetta di diritto.")
add("Je suis Maitre Edrik, j'etudie les vieilles pierres de la region.","I am Master Edrik; I study the old stones of this land.","Soy el Maestro Edrik; estudio las viejas piedras de la region.","Ich bin Meister Edrik; ich erforsche die alten Steine der Gegend.","Sono Maestro Edrik; studio le vecchie pietre della regione.")
add("On dit qu'un Temple dort sous la Vallee, scelle depuis des ages.","They say a Temple sleeps under the Valley, sealed for ages.","Dicen que un Templo duerme bajo el Valle, sellado hace eras.","Man sagt, ein Tempel schlaft unter dem Tal, seit Ewigkeiten versiegelt.","Dicono che un Tempio dorma sotto la Valle, sigillato da ere.")
add("Si tu croises des monolithes graves, ecoute-les : ils se souviennent.","If you pass carved monoliths, listen: they remember.","Si ves monolitos grabados, escuchalos: recuerdan.","Triffst du gravierte Monolithe, hore sie: sie erinnern sich.","Se incroci monoliti incisi, ascoltali: ricordano.")
add("Je m'appelle Selene. Je lis parfois ce que la lune murmure.","I am Selene. At times I read what the moon murmurs.","Me llamo Selene. A veces leo lo que la luna susurra.","Ich bin Selene. Zuweilen lese ich, was der Mond raunt.","Mi chiamo Selene. A volte leggo cio che la luna sussurra.")
add("Tu viens d'ailleurs, fille des fees... et tu cherches les tiens.","You come from elsewhere, fae daughter... and you seek your kin.","Vienes de otro lugar, hija de las hadas... y buscas a los tuyos.","Du kommst von anderswo, Feentochter... und suchst die Deinen.","Vieni da altrove, figlia delle fate... e cerchi i tuoi.")
add("Suis le fil de l'hermine : il te menera plus loin que tu ne crois.","Follow the ermine's thread: it leads farther than you think.","Sigue el hilo del armino: te llevara mas lejos de lo que crees.","Folge dem Faden des Hermelins: er fuhrt weiter, als du denkst.","Segui il filo dell'ermellino: ti portera piu lontano di quanto credi.")
add("Le vent d'Asteria porte d'etranges presages, voyageuse.","Asteria's wind carries strange omens, traveler.","El viento de Asteria trae extranos presagios, viajera.","Asterias Wind tragt seltsame Vorzeichen, Reisende.","Il vento di Asteria porta strani presagi, viaggiatrice.")

